CREATE INDEX "IX_CottageAmenities_AmenityId" ON "CottageAmenities" ("AmenityId");


CREATE INDEX "IX_CottageBookings_CottageId_StartDate_EndDate" ON "CottageBookings" ("CottageId", "StartDate", "EndDate");


CREATE INDEX "IX_CottageBookings_UserId" ON "CottageBookings" ("UserId");


CREATE UNIQUE INDEX "IX_Users_Email" ON "Users" ("Email");


SELECT setval(
    pg_get_serial_sequence('"Amenities"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Amenities") + 1,
        nextval(pg_get_serial_sequence('"Amenities"', 'Id'))),
    false);
SELECT setval(
    pg_get_serial_sequence('"Cottages"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Cottages") + 1,
        nextval(pg_get_serial_sequence('"Cottages"', 'Id'))),
    false);


